const { sbRequest } = require('/home/node/scripts/cvpro-helpers.js');
const { GeminiRotator } = require('/home/node/scripts/gemini-rotation.js');

const fifteenMinsAgo = new Date(Date.now() - 15 * 60000).toISOString();
const newMessages = await sbRequest(
  $http,
  'GET',
  `/rest/v1/messages?created_at=gt.${fifteenMinsAgo}&direction=eq.inbound&select=id,content,conversation_id&conversation_id=not.is.null`
);

if (!newMessages?.length) return [{ json: { embedded: 0 } }];

const rotator = new GeminiRotator(process.env.GEMINI_API_KEYS.split(','));
const results = [];

for (const msg of newMessages) {
  if (!msg.content?.trim()) continue;

  const convRows = await sbRequest(
    $http,
    'GET',
    `/rest/v1/conversations?id=eq.${msg.conversation_id}&select=customer_id&limit=1`
  );
  const customerId = convRows?.[0]?.customer_id;
  if (!customerId) continue;

  try {
    const embedding = await rotator.embed(msg.content);
    await sbRequest($http, 'POST', '/rest/v1/vector_memory', {
      customer_id: customerId,
      embedding,
      text_chunk: msg.content.substring(0, 500),
    });
    results.push({ customer_id: customerId, embedded: true });
  } catch (_) {
    results.push({ customer_id: customerId, embedded: false });
  }
}

return [{ json: { count: results.length, results } }];
